sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?country WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/The_Lilac_Sunbonnet> 
    <http://dbpedia.org/resource/The_Man_Without_Desire> 
  }
  OPTIONAL { ?film dbo:country ?c1 . }
  OPTIONAL { ?film dbp:country ?c2 . }
  BIND (COALESCE(?c1, ?c2) AS ?country)
}
LIMIT 100

